#include "BackgroundGen.h"
#include <cmath>
#include <cstdio>
#include "ShaderSource.h"// generated by tools/gen_shader.py

using namespace ffglex;

// 4-char unique id, 16-char name: both are what Resolume uses to identify the plugin.
// If you ever ship a different plugin, change the id so the two never clash.
static CFFGLPluginInfo PluginInfo(
	PluginFactory< BackgroundGen >,// Create method
	"ABGE",                        // Plugin unique ID
	"Background Gen",              // Plugin name (max 16 chars)
	2,                             // API major version number
	1,                             // API minor version number
	1,                             // Plugin major version number
	0,                             // Plugin minor version number
	FF_SOURCE,                     // Plugin type
	"Animated backgrounds: fog, lava, neon, aurora, smoke, gradients, lasers, lines, blocks, shapes, ink",
	"Procedural background generator. Pure GPU shader, no video files." );

BackgroundGen::BackgroundGen()
{
	// The quickstart framework prepends the version line, the built-in uniforms and one
	// uniform per parameter to our shader. We only need one extra: the integrated time.
	fragmentShaderCodeStart += "\n\t\tuniform float animTime;\n";

	// AddParam(...) calls for every parameter (Engine, Shape, Palette, Scale, ... Color1-4).
	// Order here == order in the Resolume UI; names double as GLSL uniform names.
#include "ParamsGenerated.inc"

	speedParam   = GetParam( "Speed" );
	reverseParam = GetParam( "Reverse" );

	// Append: do not change any existing parameter indices or saved compositions.
    for(unsigned int i=0;i<params.size();++i)
        if(params[i]->GetName()=="Speed") speedIndex=i;
    openIndex=static_cast<unsigned int>(params.size());
    AddParam(ffglqs::ParamEvent::Create("OpenPanel"));
    SetParamDisplayName(openIndex, "Abrir painel", false);
    // The bank starts from the generated defaults (same table that created the parameters).
    for(unsigned i=0;i<souz::ParamBank::Count;++i) applied[i]=bank.Snapshot(i);
    SetFragmentShader( BuildBackgroundShader() );
}

BackgroundGen::~BackgroundGen() { Clean(); }

FFResult BackgroundGen::Init()
{
    // SDK creates a prototype to enumerate parameters. Starting only in Init()
    // avoids a server for that prototype or for a failed GL initialization.
    if(!panel) {
        try { panel = std::make_unique<souz::PanelServer>(bank); }
        catch(const std::exception&) { FFGLLog::LogToHost("Souz Content: unable to start web panel"); }
    }
    return FF_SUCCESS; // A network failure must not break video output.
}

void BackgroundGen::Clean() { panel.reset(); }

FFResult BackgroundGen::SetFloatParameter(unsigned int index, float value)
{
    if(index==openIndex) {
        if(value>0.5f && panel) panel->Open();
        return FF_SUCCESS;
    }
    if(index<souz::ParamBank::Count) {
        if(!std::isfinite(value)) return FF_FAIL;
        // Host writes keep the original code path, and are mirrored for the panel.
        const FFResult result=ffglqs::Source::SetFloatParameter(index,value);
        if(result==FF_SUCCESS) bank.Set(index,value,false);
        return result;
    }
    return ffglqs::Source::SetFloatParameter(index,value);
}

float BackgroundGen::GetFloatParameter(unsigned int index)
{
    if(index==openIndex) return 0.0f; // Momentary action, never stored as pressed.
    // Options keep the SDK's own getter; every other value reflects web edits at once.
    if(index<souz::ParamBank::Count && souz::kPanelKind[index]!=1) return bank.Value(index);
    return ffglqs::Source::GetFloatParameter(index);
}

char* BackgroundGen::GetParameterDisplay(unsigned int index)
{
    if(index==speedIndex) {
        std::snprintf(speedDisplay,sizeof speedDisplay,"%.3f",GetFloatParameter(index));
        return speedDisplay;
    }
    if(index>=params.size()) return nullptr;
    return ffglqs::Source::GetParameterDisplay(index);
}

void BackgroundGen::ApplyPanelParams()
{
    for(unsigned i=0;i<souz::ParamBank::Count;++i) {
        const auto snapshot=bank.Snapshot(i);
        if(snapshot==applied[i]) continue;
        applied[i]=snapshot;
        // Values written by the host were already applied in SetFloatParameter.
        if(!souz::ParamBank::FromWeb(snapshot)) continue;
        ffglqs::Source::SetFloatParameter(i,souz::ParamBank::Decode(snapshot));
        // Tell Resolume its slider/persistence changed. No SDK object is touched by the worker.
        RaiseParamEvent(i,FF_EVENT_FLAG_VALUE);
    }
}

FFResult BackgroundGen::ProcessOpenGL(ProcessOpenGLStruct* input)
{
    ApplyPanelParams();
    return ffglqs::Source::ProcessOpenGL(input);
}

void BackgroundGen::Update()
{
	// deltaTime is the wall-clock time since the previous frame. It can be huge on the very
	// first frame or after the clip was paused, so clamp it.
	float dt = deltaTime;
	if( dt < 0.0f || dt > 0.25f )
		dt = 1.0f / 60.0f;

	// Speed 0..1 -> 0x..4x with a quadratic curve (fine control near the slow end).
	float s = speedParam ? speedParam->GetValue() : 0.35f;
	s       = s * s * 4.0f;

	const bool reverse = reverseParam && reverseParam->GetValue() > 0.5f;
	animTime += static_cast< double >( dt ) * s * ( reverse ? -1.0 : 1.0 );

	// The shader is already bound by Plugin::ProcessOpenGL when Update() runs.
	shader.Set( "animTime", static_cast< float >( animTime ) );
}
